export function translateSiteText(value, language) {
  if (language !== 'fr' && language !== 'rw') return value;
  const dictionary = language === 'fr' ? { ...fr, ...extraFr } : { ...rw, ...extraRw };
  if (dictionary[value]) return dictionary[value];
  if (value.startsWith('Choose the specific ') && value.endsWith(" item you're registering")) {
    const itemType = value.slice('Choose the specific '.length, -" item you're registering".length);
    return language === 'fr'
      ? `Choisissez précisément l’objet ${itemType} que vous enregistrez`
      : `Hitamo ubwoko bw’ikintu ${itemType} wandikisha`;
  }

  const dynamicTranslations = {
    fr: [
      [/^Welcome back, (.+)$/, 'Bienvenue, $1'],
      [/^All items . (.+)$/, 'Tous les objets · $1'],
      [/^Items in (.+)$/, 'Objets dans $1'],
      [/^View items? \u2193$/, 'Voir les objets ↓'],
      [/^All items · (.+)$/, 'Tous les objets · $1'],
      [/^About (.+) RWF per month$/, 'Environ $1 RWF par mois'],
      [/^Amount to pay: (.+) RWF$/, 'Montant à payer : $1 RWF'],
      [/^Current subscription expires: (.+)$/, 'L’abonnement expire le : $1'],
      [/^Found at: (.+)$/, 'Trouvé à : $1'],
      [/^Finder phone: (.+)$/, 'Téléphone de la personne ayant trouvé l’objet : $1'],
      [/^IMEI: (.+)$/, 'IMEI : $1'], [/^Serial: (.+)$/, 'N° de série : $1'], [/^VIN: (.+)$/, 'VIN : $1'],
      [/^Error: (.+)$/, 'Erreur : $1'],
    ],
    rw: [
      [/^Welcome back, (.+)$/, 'Murakaza neza, $1'],
      [/^All items . (.+)$/, 'Ibintu byose · $1'],
      [/^Items in (.+)$/, 'Ibintu biri mu $1'],
      [/^View items? \u2193$/, 'Reba ibintu ↓'],
      [/^All items · (.+)$/, 'Ibintu byose · $1'],
      [/^About (.+) RWF per month$/, 'Hafi ya $1 RWF buri kwezi'],
      [/^Amount to pay: (.+) RWF$/, 'Amafaranga yo kwishyura: $1 RWF'],
      [/^Current subscription expires: (.+)$/, 'Ifatabuguzi rirangira: $1'],
      [/^Found at: (.+)$/, 'Cyabonetse: $1'],
      [/^Finder phone: (.+)$/, 'Telefoni y’uwakibonye: $1'],
      [/^IMEI: (.+)$/, 'IMEI: $1'], [/^Serial: (.+)$/, 'Serial: $1'], [/^VIN: (.+)$/, 'VIN: $1'],
      [/^Error: (.+)$/, 'Ikosa: $1'],
    ],
  };
  if (value === 'Welcome back, ') return language === 'fr' ? 'Bienvenue, ' : 'Murakaza neza, ';
  if (language === 'fr' && value.startsWith('. Here is your platform overview.')) return '. Voici un aperçu de votre plateforme.';
  if (language === 'rw' && value.startsWith('. Here is your platform overview.')) return '. Dore uko urubuga ruhagaze.';
  const patterns = dynamicTranslations[language] || [];
  for (const [pattern, replacement] of patterns) {
    if (pattern.test(value)) return value.replace(pattern, replacement);
  }
  return value;
}
